def preguntar(pregunta, correcta):
    r = input(pregunta).lower()
    if r == correcta:
        print("Correcto")
        return 1
    print("Incorrecto")
    return 0

def mensaje_final(puntaje):
    if puntaje == 3:
        return "¡Excelente!"
    elif puntaje == 2:
        return "Bien"
    return "Sigue practicando"

preguntas = ["¿Cuántas patas tiene una araña? ", "¿De qué color es el cielo despejado? ", "¿Cuánto es 9 x 7? "]
respuestas = ["8", "azul", "63"]
puntaje = 0
for i in range(len(preguntas)):
    puntaje += preguntar(preguntas[i], respuestas[i])
print("Puntaje:", puntaje, "de", len(preguntas))
print(mensaje_final(puntaje))

extra.solucion:
def sumar(a, b):
    return a + b

def restar(a, b):
    return a - b

def multiplicar(a, b):
    return a * b

def dividir(a, b):
    return a / b

x = int(input("Primer número: "))
y = int(input("Segundo número: "))
op = input("Operación (+ - * /): ")
if op == "+":
    print("Resultado:", sumar(x, y))
elif op == "-":
    print("Resultado:", restar(x, y))
elif op == "*":
    print("Resultado:", multiplicar(x, y))
elif op == "/":
    if y == 0:
        print("No se puede dividir entre cero")
    else:
        print("Resultado:", dividir(x, y))
else:
    print("Operación desconocida")

